// Saves a card token (generated by the Mercado Pago Android SDK) as a reusable Customer Card, so
// the client can pay with it later without redigitando dados. See
// specs/018-mercadopago-payments/research.md §2 and contracts/mercadopago-edge-functions.md.
import { createClient } from "npm:@supabase/supabase-js@2";

const json = (status: number, body: unknown) => new Response(JSON.stringify(body), {
  status,
  headers: { "content-type": "application/json; charset=utf-8" },
});

Deno.serve(async (request) => {
  if (request.method !== "POST") return json(405, { code: "METHOD_NOT_ALLOWED" });
  const supabaseUrl = Deno.env.get("SUPABASE_URL");
  const anonKey = Deno.env.get("SUPABASE_ANON_KEY");
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  const accessToken = Deno.env.get("MP_ACCESS_TOKEN");
  if (!supabaseUrl || !anonKey || !serviceKey || !accessToken) {
    return json(503, { code: "SERVICE_UNAVAILABLE" });
  }

  const authorization = request.headers.get("authorization") ?? "";
  const userClient = createClient(supabaseUrl, anonKey, {
    global: { headers: { Authorization: authorization } },
  });
  const { data: userData, error: userError } = await userClient.auth.getUser();
  if (userError || !userData.user) return json(401, { code: "SESSION_REQUIRED" });

  let payload: Record<string, unknown>;
  try { payload = await request.json(); } catch { return json(400, { code: "INVALID_INPUT" }); }
  const cardToken = payload.card_token;
  if (typeof cardToken !== "string" || cardToken.length === 0) {
    return json(400, { code: "INVALID_INPUT" });
  }

  const admin = createClient(supabaseUrl, serviceKey, { auth: { persistSession: false } });

  // One Mercado Pago Customer per PitGo client, reused across every saved card.
  const { data: existingCard } = await admin.from("saved_cards").select("mp_customer_id")
    .eq("client_id", userData.user.id).limit(1).maybeSingle();
  let customerId = existingCard?.mp_customer_id as string | undefined;
  if (!customerId) {
    const customerEmail = userData.user.email;
    if (!customerEmail) return json(422, { code: "CUSTOMER_EMAIL_REQUIRED" });
    const createCustomer = await fetch("https://api.mercadopago.com/v1/customers", {
      method: "POST",
      headers: { Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json" },
      body: JSON.stringify({ email: customerEmail }),
    });
    if (!createCustomer.ok && createCustomer.status !== 400) {
      return json(502, {
        code: "PROVIDER_UNAVAILABLE",
        stage: "CUSTOMER_CREATE",
        provider_status: createCustomer.status,
      });
    }
    const customerBody = await createCustomer.json();
    // Depending on the API response version, an existing customer's id can be returned either
    // as cause[0].data itself or nested in cause[0].data.id.
    const causeData = customerBody.cause?.[0]?.data;
    customerId = customerBody.id ??
      (typeof causeData === "string" || typeof causeData === "number"
        ? String(causeData)
        : causeData?.id == null ? undefined : String(causeData.id));

    // Some duplicate-customer responses omit the id altogether. Resolve it by the same exact
    // email instead of leaving an orphan Customer that makes every later retry fail.
    if (!customerId && createCustomer.status === 400) {
      const searchCustomer = await fetch(
        `https://api.mercadopago.com/v1/customers/search?email=${encodeURIComponent(customerEmail)}`,
        { headers: { Authorization: `Bearer ${accessToken}` } },
      );
      if (searchCustomer.ok) {
        const searchBody = await searchCustomer.json();
        customerId = searchBody.results?.[0]?.id == null
          ? undefined
          : String(searchBody.results[0].id);
      }
    }
    if (!customerId) {
      return json(502, {
        code: "PROVIDER_UNAVAILABLE",
        stage: "CUSTOMER_RESOLVE",
        provider_status: createCustomer.status,
      });
    }
  }

  const addCard = await fetch(`https://api.mercadopago.com/v1/customers/${customerId}/cards`, {
    method: "POST",
    headers: { Authorization: `Bearer ${accessToken}`, "Content-Type": "application/json" },
    body: JSON.stringify({ token: cardToken }),
  });
  if (!addCard.ok) {
    if (addCard.status === 400 || addCard.status === 422) return json(422, { code: "CARD_REJECTED" });
    return json(502, {
      code: "PROVIDER_UNAVAILABLE",
      stage: "CARD_ATTACH",
      provider_status: addCard.status,
    });
  }
  const card = await addCard.json();
  const brand = String(card.payment_method?.id ?? card.payment_method?.name ?? "unknown");
  const lastFour = String(card.last_four_digits ?? "0000");

  const { data: saved, error: insertError } = await admin.from("saved_cards").insert({
    client_id: userData.user.id,
    mp_customer_id: customerId,
    mp_card_id: String(card.id),
    brand,
    last_four_digits: lastFour,
  }).select().single();
  if (insertError || !saved) {
    return json(502, { code: "PROVIDER_UNAVAILABLE", stage: "CARD_STORE" });
  }

  return json(200, {
    saved_card_id: saved.id,
    brand: saved.brand,
    last_four_digits: saved.last_four_digits,
  });
});
